OGR_ASSIGN_SCALAR_VAR_REAL(kV558_CONSTvt0,sV558_CONSTvt0);
OGR_ASSIGN_SCALAR_VAR_REAL(kV658_burst_noise,sV658_burst_noise);
ogr_add_file_in_instance(-1, block,"STDIN",false);ogr_add_file_in_instance(-1, block,"STDOUT",false);ogr_add_file_in_instance(-1, block,"STDERR",false);ogr_add_file_in_instance(-1, block,"STDOUT",true);
SET_ELDO_BLOCK_IDX(ogr_solver_index_objet_courant());
