static void ams_free_simulation(BLOCK_ENVIR_DECL UNUSED){
BLOCK_DECL UNUSED = BLOCK_ENVIR_CAST;
if (ogr_data(bypassvalues)) { free(ogr_data(bypassvalues)); ogr_data(bypassvalues)=NULL; }

/* avoid empty function */
if (ogr_display_str) free(ogr_display_str);free(ogr_data(analog_operators_size));free(OGR_DEVICE_CODE_GEN_DATA(block));
} /* ams_free_simulation */
static void ams_update_temperature(BLOCK_ENVIR_DECL UNUSED)
{BLOCK_DECL UNUSED = BLOCK_ENVIR_CAST;
if(!ogr_data(update_temperature_ready )) return;
ogr_data(update_temperature_flag ) = true;
ams_each_iter(block,0);
ogr_data(update_temperature_flag ) = false;
} /* ams_update_temperature */
